    const sidebar=mount.querySelector('.role-sidebar'), main=mount.querySelector('.role-main'), menuButton=mount.querySelector('.role-menu');
    sidebar.id='role-sidebar-nav';
    menuButton.setAttribute('aria-controls',sidebar.id);
    menuButton.setAttribute('aria-label',`Open ${role} navigation`);
    menuButton.prepend(navIcon('menu'));
    const closeButton=document.createElement('button'); closeButton.type='button'; closeButton.className='role-drawer-close'; closeButton.textContent='Close';
    closeButton.setAttribute('aria-label','Close navigation menu'); closeButton.prepend(navIcon('close')); sidebar.append(closeButton);
    const backdrop=document.createElement('button'); backdrop.type='button'; backdrop.className='role-drawer-backdrop'; backdrop.setAttribute('aria-label','Close navigation menu'); backdrop.hidden=true; mount.prepend(backdrop);
