    menuButton.addEventListener('click',()=>setDrawer(true));
    closeButton.addEventListener('click',()=>setDrawer(false,true));
    backdrop.addEventListener('click',()=>setDrawer(false,true));
    const topbarActions=document.createElement('div'); topbarActions.className='role-topbar-actions';
    const roleSwitch=mount.querySelector('.role-switch'); roleSwitch.before(topbarActions); topbarActions.append(roleSwitch);
    const brandLogo=mount.querySelector('.role-brand img'), logoBox=document.createElement('span');
